<template><ion-page><ion-content><main class="page-shell"><section class="form-card"><h1 class="page-title">Recuperar senha</h1><p class="page-subtitle">Informe seu e-mail para receber o link de redefinição.</p><form @submit.prevent="submit"><ion-item class="field" lines="none"><ion-input v-model="email" label="E-mail" label-placement="stacked" type="email" autocomplete="email" required /></ion-item><p v-if="message" class="notice" :class="success ? 'success' : 'error'">{{ message }}</p><ion-button expand="block" type="submit" :disabled="loading">{{ loading ? 'Enviando…' : 'Enviar link' }}</ion-button></form><div class="center"><router-link class="inline-link" to="/login">Voltar ao login</router-link></div></section></main></ion-content></ion-page></template>
<script setup lang="ts">
import { ref } from 'vue'; import { IonButton, IonContent, IonInput, IonItem, IonPage } from '@ionic/vue'; import { resetPassword } from '../services/authService'; import { friendlyError } from '../utils/errors'
const email = ref(''), loading = ref(false), message = ref(''), success = ref(false)
async function submit() { message.value = ''; if (!email.value.trim()) { message.value = 'Informe seu e-mail.'; return }; loading.value = true; try { await resetPassword(email.value); success.value = true; message.value = 'Se houver uma conta para este e-mail, você receberá as instruções de recuperação.' } catch (e) { success.value = false; message.value = friendlyError(e) } finally { loading.value = false } }
</script>
